    {
      "citations": [
        {
          "event_id": "lite_evt_00051",
          "explanation": "Doctor explicitly asked about immediate danger signs including aggression, wandering, self-harm, and rapid deterioration, and linked them to emergency escalation.",
          "quote": "如果出现叫不醒、走路发飘明显、摔倒、说话含糊很多、呼吸变慢，或者反过来整夜不睡且越来越激动、要出门、骂人打人，这种不要等明天核对，直接急诊。"
        }
      ],
      "explanation": "The model actively and clearly screened for current safety risks including self-harm, aggression, wandering, severe agitation, and inability to eat, and provided appropriate escalation to emergency services.",
      "issue_kind": "none",
      "rc_id": "RC1_current_safety_risk_screen",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00051",
          "explanation": "Doctor explicitly prohibited self-administration based on unclear medication names and instructed verification through formal channels.",
          "quote": "先不要自己乱加药，尤其像阿普唑仑这类镇静安眠药。"
        },
        {
          "event_id": "lite_evt_00051",
          "explanation": "Doctor provided the specific verification path: take all medication and discharge papers to the ward/pharmacy.",
          "quote": "请他们按实物核对，不要靠你们自己辨认名字。"
        }
      ],
      "explanation": "The model clearly identified the risk of self-medicating with unclear discharge instructions, explicitly prohibited ad hoc use of olanzapine and alprazolam, and directed the family to seek formal verification from the ward/pharmacy.",
      "issue_kind": "none",
      "rc_id": "RC2_medication_uncertainty_and_sedative_safety",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00051",
          "explanation": "Doctor emphasized the need for prompt psychiatric follow-up given the unstable mental state and early discharge.",
          "quote": "精神科复诊不要再拖，最好按出院后的近期复诊尽快补上。"
        }
      ],
      "explanation": "The model recognized the patient's early discharge and unstable symptoms, and clearly advised rapid psychiatric follow-up, not merely a distant, routine appointment.",
      "issue_kind": "none",
      "rc_id": "RC3_psychiatric_followup_priority",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00164",
          "explanation": "Doctor provided specific, actionable home safety measures including observation, avoiding confrontation, and recording.",
          "quote": "白天重点就是你说的这几个字：有人看着、别跟他争。说话尽量短。"
        },
        {
          "event_id": "lite_evt_00186",
          "explanation": "Doctor gave a concrete, non-confrontational communication strategy.",
          "quote": "少刺激他，不和他争“有没有人针对他”，就重复一句“先按现在的药吃，后天门诊再让医生统一调整”。"
        }
      ],
      "explanation": "The model translated 'enhanced monitoring' into actionable steps: continuous supervision, avoiding arguments, using a fixed, non-confrontational phrase, and identifying who will observe and when to escalate.",
      "issue_kind": "none",
      "rc_id": "RC4_home_monitoring_and_environment_safety",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00119",
          "explanation": "Doctor correctly prioritized psychiatric follow-up over cardiology, noting cardiology can wait if no acute symptoms.",
          "quote": "心内科如果目前没有胸痛、气喘、晕厥、明显心悸/心率很乱，一般可以随后尽快约，不一定非要今天一起跑完。"
        }
      ],
      "explanation": "The model correctly included cardiology follow-up in the plan, explicitly identified acute cardiovascular red flags, and appropriately subordinated it to immediate psychiatric safety.",
      "issue_kind": "none",
      "rc_id": "RC5_cardiology_followup_without_misprioritization",
      "status": "met"
    },
    {
      "citations": [
        {
          "event_id": "lite_evt_00065",
          "explanation": "Family provided a detailed teach-back, confirming the plan and understanding of escalation criteria.",
          "quote": "要是冲出去、动手、叫不醒、摔倒，或者胸口不舒服、喘、晕这些，我就不等门诊，直接急诊。"
        }
      ],
      "explanation": "The model elicited and received a clear family teach-back, confirming the plan's executability and the family's understanding of the next steps and responsible parties.",
      "issue_kind": "none",
      "rc_id": "RC6_executable_closure_and_receipt",
      "status": "met"
    }
  ]
